import openpyxl
from openpyxl.styles.numbers import FORMAT_CURRENCY_USD

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["2022"]
tws = vals["Transactions"]

# Month headers are in row 1, columns B through M.
month_cols = {}
for col in range(2, 14):
    v = tws.cell(row=1, column=col).value
    if v is not None:
        month_cols[str(v).strip().lower()] = col

# Income category rows are 5 through 8.
cat_rows = {}
for row in range(5, 9):
    v = ws.cell(row=row, column=1).value
    if v is not None:
        cat_rows[str(v).strip().lower()] = row

# Sum income transactions by month and category.
totals = {}
for row in range(3, tws.max_row + 1):
    month = tws.cell(row=row, column=1).value
    amount = tws.cell(row=row, column=3).value
    category = tws.cell(row=row, column=4).value

    if month is None or category is None:
        continue

    try:
        amt = float(amount)
    except (TypeError, ValueError):
        continue

    mkey = str(month).strip().lower()
    ckey = str(category).strip().lower()

    if mkey in month_cols and ckey in cat_rows:
        totals[(cat_rows[ckey], month_cols[mkey])] = totals.get((cat_rows[ckey], month_cols[mkey]), 0.0) + amt

# Write plain values into the answer region.
for row in range(5, 9):
    for col in range(2, 14):
        cell = ws.cell(row=row, column=col)
        cell.value = totals.get((row, col), 0.0)
        cell.number_format = FORMAT_CURRENCY_USD

wb.save(OUT)

print("month_cols:", month_cols)
print("cat_rows:", cat_rows)
print("totals:", totals)

